function readJsonBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    let bodyTooLarge = false;
    let settled = false;
    const fail = (reason: 'too-large' | 'invalid-json'): void => {
      if (settled) return;
      settled = true;
      reject(new Error(reason));
    };
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      // 超限只标记、停止缓存，绝不销毁连接：继续把剩余请求体排空（drain），
      // 否则未读完的请求数据会导致服务端随后写出的响应被 TCP RST，客户端只看到连接重置。
      if (size > MAX_BODY_BYTES) {
        bodyTooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!bodyTooLarge) chunks.push(chunk);
    });
    req.on('end', () => {
      if (bodyTooLarge) {
        fail('too-large');
        return;
      }
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
      } catch {
        fail('invalid-json');
      }
    });
    req.on('error', () => fail('invalid-json'));
  });
}

