const net = require("node:net");
const LIMIT = 1_048_576;

function sendRaw({ chunks, headers, delayMs = 0 }) {
  return new Promise((resolve) => {
    const client = net.connect(18765, "127.0.0.1");
    let data = Buffer.alloc(0);
    client.on("connect", () => {
      client.write(`POST /api/products HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\n${headers}\r\n`);
      let i = 0;
      const next = () => {
        if (i >= chunks.length) { client.end(); return; }
        client.write(chunks[i++]);
        if (delayMs > 0) setTimeout(next, delayMs);
        else setImmediate(next);
      };
      next();
    });
    client.on("data", (c) => (data = Buffer.concat([data, c])));
    client.on("close", (hadErr) => resolve({ raw: data.toString(), hadErr }));
    client.on("error", (e) => resolve({ raw: data.toString(), hadErr: true, err: e.message }));
  });
